const { normalizeFlatKey, SHARED_COMPONENTS_PREFIX } = require('./normalizeFlatKey');

function isSharedComponentsKey(key) {
  return key.startsWith(SHARED_COMPONENTS_PREFIX);
}

function detectMfeNamespace(mfeEntries) {
  const keys = Object.keys(mfeEntries);
  if (keys.length === 0) {
    return null;
  }

  const namespaces = [...new Set(keys.map((key) => key.split('.')[0]).filter(Boolean))];
  if (namespaces.length === 1) {
    return namespaces[0];
  }

  console.warn(
    `⚠️  Multiple MFE namespaces found (${namespaces.join(', ')}); using "${namespaces[0]}" for shared entries`
  );
  return namespaces[0];
}

function assignEntry(target, key, value) {
  target[key] = value;
}

function mergeSharedUnderMfeNamespace(mfeEntries, sharedEntries) {
  const result = { ...mfeEntries };
  const mfeNamespace = detectMfeNamespace(mfeEntries);

  if (!mfeNamespace) {
    if (Object.keys(sharedEntries).length > 0) {
      console.warn('⚠️  No MFE namespace detected; shared entries included at root level');
      Object.assign(result, sharedEntries);
    }
    return result;
  }

  Object.keys(sharedEntries).forEach((key) => {
    assignEntry(result, `${mfeNamespace}.${key}`, sharedEntries[key]);
  });

  return result;
}

module.exports = {
  isSharedComponentsKey,
  detectMfeNamespace,
  mergeSharedUnderMfeNamespace,
  normalizeFlatKey,
  SHARED_COMPONENTS_PREFIX,
};
